<template>
  <div class="advanced-parameters">
    <!-- 折叠控制按钮 -->
    <div class="collapse-header" @click="toggleCollapse">
      <h3 class="section-title">{{ t('advancedParameters') }}</h3>
      <button class="collapse-button">
        <span>{{ isExpanded ? t('hideAdvanced') : t('showAdvanced') }}</span>
        <l-img 
          src="/static/images/up-icon-blue.png" 
          w="18px" 
          h="18px" 
          :class="{ 'rotated': isExpanded }"
        />
      </button>
    </div>

    <!-- 可折叠内容区域 -->
    <div class="collapse-content" v-show="isExpanded">
      <!-- 1. 正向提示词 -->
      <div class="form-section">
        <label class="form-label">{{ t('promptOptional') }}</label>
        <p class="form-help">{{ t('promptDescription') }}</p>
        <el-input
          :model-value="modelValue.prompt"
          @update:model-value="value => updateValue('prompt', value)"
          type="textarea"
          :placeholder="t('promptPlaceholder')"
          :rows="3"
          class="textarea-input"
        />
      </div>

      <!-- 2. 负向提示词 -->
      <div class="form-section">
        <label class="form-label">{{ t('negativePromptOptional') }}</label>
        <p class="form-help">{{ t('negativePromptDescription') }}</p>
        <el-input
          :model-value="modelValue.negativePrompt"
          @update:model-value="value => updateValue('negativePrompt', value)"
          type="textarea"
          :placeholder="t('negativePromptDescription')"
          :rows="3"
          class="textarea-input"
        />
      </div>

      <!-- 3. 创意度滑块 -->
      <div class="form-section">
        <div class="label-with-value">
          <label class="form-label">{{ t('creativity') }}</label>
          <span class="value-display">{{ t('value') }}: {{ modelValue.creativity }}</span>
        </div>
        <p class="form-help">{{ t('creativityDescription') }}</p>
        
        <div class="creativity-controls">
          <el-input
            :model-value="data.creativity"
            @update:model-value="value => updateValue('creativity', value)"
            type="number"
            :min="0"
            :max="1"
            :step="0.1"
            class="number-input"
          />
          <el-slider
            :model-value="data.creativity"
            @update:model-value="value => updateValue('creativity', value)"
            :min="0"
            :max="1"
            :step="0.1"
            class="creativity-slider"
          />
        </div>
      </div>

      <!-- 4. 手部修复 -->
      <div class="form-section">
        <label class="form-label">{{ t('handFix') }}</label>
        <p class="form-help">{{ t('handFixDescription') }}</p>
        <OptionSelector
          :model-value="modelValue.handFix"
          @update:model-value="value => updateValue('handFix', value)"
          :options="handFixOptions"
          :placeholder="t('selectHandFixOption')"
          :show-radio="false"
          :show-description="false"
        />
      </div>

      <!-- 5. 种子值 -->
      <div class="form-section">
        <label class="form-label">{{ t('seedOptional') }}</label>
        <p class="form-help">{{ t('seedDescription') }}</p>
        <el-input
          :model-value="modelValue.seed"
          @update:model-value="value => updateValue('seed', value)"
          type="number"
          :placeholder="t('seedPlaceholder')"
          class="seed-input"
        />
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed,watch } from 'vue';
import { useI18n } from 'vue-i18n';
import OptionSelector from '@/components/business/components/option-selector.vue';
import LImg from '@/components/l-img.vue';

const { t } = useI18n();

const isExpanded = ref(false);

// 手部修复选项 - 不包含描述
const handFixOptions = ref([
  {
    value: 'disabled',
    label: 'Disabled'
  },
  {
    value: 'hands-only',
    label: 'Hands Only'
  },
  {
    value: 'image-and-hands',
    label: 'Image and Hands'
  }
]);

const props = defineProps({
  modelValue: {
    type: Object,
    required: true
  }
});

const emit = defineEmits(['update:modelValue', 'expand-change']);

const toggleCollapse = () => {
  isExpanded.value = !isExpanded.value;
  emit('expand-change', isExpanded.value);
};

const data = ref({ ...props.modelValue })   // 创建副本
watch(() => props.modelValue, v => { data.value = { ...v } })

const updateValue = (key, value) => {
  const next = { ...data.value, [key]: value }
  data.value = next
  emit('update:modelValue', next)
};
</script>

